// Matches the application to an open job, skips repeats and keeps the PDF for the AI.
const form = $('Job Application Form').first();
const a = form.json;
const email = String(a.email || '').trim().toLowerCase();
const position = String(a.position || '').trim();
const job = $('Read Jobs').all().map(i => i.json)
  .find(j => String(j.Title || '').trim().toLowerCase() === position.toLowerCase() && String(j.Status || '').trim().toLowerCase() === 'open') || null;
const key = email + '|' + (job ? String(job['Job ID']) : position.toLowerCase());
const repeat = $('Read Candidates').all().some(i => String(i.json['Dedupe Key'] || '') === key);
const cv = Object.values(form.binary || {}).find(b => /pdf/i.test(b.mimeType || '') || /\.pdf$/i.test(b.fileName || ''));
const issue = !job ? 'No open job called "' + position + '" in the Jobs tab' : !cv ? 'No PDF CV attached' : '';
return [{
  json: {
    route: repeat ? 'repeat' : issue ? 'unscreened' : 'screen',
    candidate_id: 'CAND-' + DateTime.now().toFormat('yyMMdd') + '-' + $execution.id,
    applied_at: DateTime.now().toISO(),
    name: String(a.name || '').trim(),
    email,
    phone: String(a.phone || '').trim(),
    position,
    job,
    job_id: job ? String(job['Job ID']) : '',
    interviewer: job ? String(job['Interviewer Email'] || '').trim() : '',
    linkedin: String(a.linkedin || '').trim(),
    salary: String(a.salary || '').trim(),
    file_name: cv?.fileName || 'cv.pdf',
    dedupe_key: key,
    issue,
  },
  binary: cv ? { cv } : {},
}];

