// Turns the AI results into a recommendation and puts the CV back on the item for the upload.
const s = $('Hiring Settings').first().json;
const app = $('Check Application').first();
const read = j => { const t = j?.output?.[0]?.content?.[0]?.text; return t && typeof t === 'object' ? t : null; };
const ex = $('Extract Profile').first().json;
const profile = read(ex);
const sc = $('Score Candidate').isExecuted ? $('Score Candidate').first().json : null;
const score = read(sc);
const why = j => (j?.error ? ': ' + String(j.error.message ?? j.error).slice(0, 200) : '');
let issue = '', recommendation = 'Review', status = 'Review', overall = '', must = [];
if (!profile) issue = 'The AI could not read the CV' + why(ex);
else if (profile.is_cv !== true) issue = 'The file does not look like a CV';
else if (!score || !Number.isFinite(Number(score.overall_score))) issue = 'The AI could not score the CV' + why(sc);
else {
  overall = Math.round(Number(score.overall_score));
  must = Array.isArray(score.must_haves) ? score.must_haves : [];
  const notMet = must.filter(m => m.status === 'not_met').length;
  const partly = must.filter(m => m.status === 'partly').length;
  if (notMet || overall < Number(s.reject_below)) recommendation = 'Reject';
  else if (overall >= Number(s.shortlist_score) && !partly) recommendation = 'Shortlist';
  status = recommendation === 'Shortlist' ? (s.auto_invite === true ? 'Invited' : 'Shortlisted') : recommendation === 'Reject' ? 'Reject suggested' : 'Review';
}
const lines = (a, numbered) => (Array.isArray(a) ? a : []).map((x, i) => (numbered ? (i + 1) + '. ' : '- ') + x).join('\n');
const open = must.filter(m => m.status !== 'met');
return [{
  json: {
    score: overall, recommendation, status, issue,
    must_haves: must.length ? must.length - open.length + '/' + must.length + ' met' + (open.length ? '. Missing: ' + open.map(m => m.requirement + ' (' + m.status.replace('_', ' ') + ')').join('; ') : '') : '',
    summary: score?.summary || '', strengths: lines(score?.strengths), gaps: lines(score?.gaps), questions: lines(score?.interview_questions, true),
  },
  binary: app.binary,
}];

// Invites and rejections HR confirmed in the Candidates tab, plus the morning digest.
const s = $('Hiring Settings').first().json;
const rows = $input.all().map(i => i.json).filter(r => r['Candidate ID']);
const now = DateTime.now();
const first = r => String(r.Name || '').trim().split(/\s+/)[0] || 'there';
const fill = (t, r) => String(t).replace(/\{name\}/g, first(r)).replace(/\{position\}/g, r.Position || 'the role')
  .replace(/\{company\}/g, s.company_name).replace(/\{sender\}/g, s.hr_name);
const out = [];
for (const r of rows) {
  if (r.Status === 'Invite') out.push({ json: { action: 'invite', ...r } });
  if (r.Status === 'Rejected' && !r['Rejection Sent At'] && r.Email) out.push({ json: { action: 'reject', candidate_id: r['Candidate ID'], to: r.Email, subject: fill(s.rejection_subject, r), body: fill(s.rejection_body, r) } });
}
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const score = r => (r.Score === '' || r.Score === undefined ? -1 : Number(r.Score));
const fresh = rows.filter(r => { const d = DateTime.fromISO(String(r['Applied At'] || '')); return d.isValid && d >= now.minus({ hours: 24 }); });
const byJob = {};
for (const r of fresh) (byJob[r.Position || '-'] ??= []).push(r);
const waiting = rows.filter(r => ['Review', 'Shortlisted', 'Reject suggested'].includes(r.Status)).sort((a, b) => score(b) - score(a));
const soon = rows.filter(r => r.Status === 'Interview booked')
  .map(r => ({ r, t: DateTime.fromFormat(String(r['Interview At'] || ''), 'yyyy-MM-dd HH:mm') }))
  .filter(x => x.t.isValid && x.t >= now.startOf('day') && x.t < now.plus({ days: 2 }).startOf('day')).sort((a, b) => a.t - b.t);
const stuck = rows.filter(r => ['Needs scheduling', 'No response'].includes(r.Status));
const invites = out.filter(o => o.json.action === 'invite').length;
const rejects = out.filter(o => o.json.action === 'reject').length;
if (fresh.length || waiting.length || soon.length || stuck.length || invites || rejects) {
  const cv = r => (r.CV ? '<a href="' + esc(r.CV) + '">CV</a>' : '');
  const table = (head, body) => '<table cellpadding="6" style="border-collapse:collapse;border:1px solid #ddd"><tr>' + head.map(h => '<th align="left">' + h + '</th>').join('') + '</tr>' + body + '</table>';
  let html = '<div style="font-family:Arial,sans-serif;font-size:14px">';
  for (const [job, list] of Object.entries(byJob)) {
    list.sort((a, b) => score(b) - score(a));
    html += '<h3 style="margin-bottom:4px">New for ' + esc(job) + ' (' + list.length + ')</h3>' + table(['#', 'Candidate', 'Score', 'AI says', 'Status', ''],
      list.map((r, i) => '<tr><td>' + (i + 1) + '</td><td>' + esc(r.Name) + '<br><span style="color:#666">' + esc(r.Summary || r.Issues) + '</span></td><td>' + esc(r.Score) + '</td><td>' + esc(r.Recommendation) + '</td><td>' + esc(r.Status) + '</td><td>' + cv(r) + '</td></tr>').join(''));
  }
  if (soon.length) html += '<h3 style="margin-bottom:4px">Interviews today and tomorrow</h3><ul>' + soon.map(x => '<li>' + esc(x.t.toFormat('ccc d LLL, HH:mm')) + ' · ' + esc(x.r.Name) + ' · ' + esc(x.r.Position) + (x.r['Meet Link'] ? ' · <a href="' + esc(x.r['Meet Link']) + '">Meet</a>' : '') + '</li>').join('') + '</ul>';
  if (waiting.length) html += '<h3 style="margin-bottom:4px">Waiting for your decision (' + waiting.length + ')</h3><ul>' + waiting.slice(0, 20).map(r => '<li>' + esc(r.Name) + ' · ' + esc(r.Position) + ' · ' + (score(r) >= 0 ? 'score ' + esc(r.Score) + ' · ' : '') + esc(r.Status) + (r.Issues ? ' · ' + esc(r.Issues) : '') + ' ' + cv(r) + '</li>').join('') + '</ul>';
  if (stuck.length) html += '<h3 style="margin-bottom:4px">Interview not booked (' + stuck.length + ')</h3><ul>' + stuck.map(r => '<li>' + esc(r.Name) + ' · ' + esc(r.Status) + (r.Notes ? ' · ' + esc(r.Notes) : '') + '</li>').join('') + '</ul>';
  html += '<p style="color:#666">Today: ' + invites + ' interview invitation(s) and ' + rejects + ' rejection email(s) sent from your decisions. Set Status to <b>Invite</b> or <b>Rejected</b> in the Candidates tab and the next run takes care of it.</p></div>';
  out.push({ json: { action: 'digest', subject: 'Hiring digest: ' + fresh.length + ' new, ' + waiting.length + ' waiting for you, ' + soon.length + ' interview(s) soon', html } });
}
return out;

// Free interview times on working days: busy blocks plus a buffer are avoided, at most two times per day.
const s = $('When Booking Starts').first().json.settings;
const busy = $input.all().map(i => i.json).filter(b => b.start && b.end).map(b => ({ start: DateTime.fromISO(b.start), end: DateTime.fromISO(b.end) }));
const len = Number(s.interview_minutes) || 45, buffer = Number(s.buffer_minutes) || 0;
const earliest = DateTime.now().plus({ hours: Number(s.min_notice_hours) || 0 });
const times = [];
for (let d = 0; d <= Number(s.days_ahead); d++) {
  const day = DateTime.now().plus({ days: d }).startOf('day');
  if (day.weekday > 5) continue;
  const close = day.set({ hour: Number(s.workday_end) });
  const picked = [];
  for (let t = day.set({ hour: Number(s.workday_start) }); t.plus({ minutes: len }) <= close; t = t.plus({ minutes: 30 })) {
    const end = t.plus({ minutes: len });
    if (t < earliest) continue;
    if (busy.some(b => t < b.end.plus({ minutes: buffer }) && end > b.start.minus({ minutes: buffer }))) continue;
    if (picked.length && t < picked[picked.length - 1].plus({ hours: 3 })) continue;
    picked.push(t);
    if (picked.length === 2) break;
  }
  times.push(...picked);
}
const slots = times.slice(0, Number(s.max_slots) || 6).map(t => ({
  label: t.toFormat('cccc d LLL, HH:mm') + '–' + t.plus({ minutes: len }).toFormat('HH:mm') + ' ' + s.timezone_label,
  start: t.toISO(),
  end: t.plus({ minutes: len }).toISO(),
}));
const none = 'None of these times work for me';
return [{ json: {
  slots,
  form_fields: [
    { fieldLabel: 'Interview time', fieldType: 'dropdown', fieldOptions: { values: [...slots.map(x => ({ option: x.label })), { option: none }] }, requiredField: true },
    { fieldLabel: 'Anything we should know?', fieldType: 'textarea', placeholder: 'Optional, e.g. other times that suit you', requiredField: false },
  ],
  status: 'Needs scheduling',
  note: slots.length ? '' : 'No free interview time in the next ' + s.days_ahead + ' days. Please schedule by hand.',
} }];

