// The chosen time. Without "data" the wait ran out before the candidate answered.
const s = $('When Booking Starts').first().json.settings;
const plan = $('Plan Slots').first().json;
const r = $input.first().json;
if (!r.data) return [{ json: { outcome: 'no_response', status: 'No response', note: 'Did not pick an interview time within ' + s.reply_days + ' days.' } }];
const picked = String(r.data['Interview time'] ?? '');
const note = String(r.data['Anything we should know?'] ?? '').trim();
const slot = plan.slots.find(x => x.label === picked);
if (!slot) return [{ json: { outcome: 'other_time', status: 'Needs scheduling', note: 'None of the offered times work.' + (note ? ' Candidate wrote: ' + note : '') } }];
return [{ json: { outcome: 'picked', slot, note } }];

