    '<h4>Strengths</h4>' + list(c.Strengths) + '<h4>Gaps to probe</h4>' + list(c.Gaps) + '<h4>Suggested questions</h4>' + list(c['Interview Questions']) +
    '<p style="color:#666">The score is a suggestion from an anonymized profile. Please judge the interview on its own.</p></div>';
})() }}

